package ctxflow

import (
	"sync/atomic"
	"time"
)

// PROBLEM
//
// FetchNoCtx does a slow job in 5 steps and cannot be told to stop. Once it
// starts it runs to the end, even if the caller gave up after the first step.
// Nobody is waiting for the result any more, but the work, and everything it
// holds (a connection, memory, a goroutine), stays in use.
//
// TRY IT
//
// Read TestBefore_WorkContinuesAfterTheCallerGivesUp in ctxflow_test.go. The
// caller walks away after 30ms. Half a second later, all 5 steps have still run.
//
// Do not edit this file. Your work goes in after.go.

const (
	totalSteps = 5
	stepDelay  = 20 * time.Millisecond
)

// FetchNoCtx runs every step and counts each one in done. Nothing can stop it.
func FetchNoCtx(done *atomic.Int64) {
	for i := 0; i < totalSteps; i++ {
		time.Sleep(stepDelay)
		done.Add(1)
	}
}
